    window.__dbg = function(){ return { target: target, cur: cur, flip: flip, scheduled: _lastScheduledYear, holdTimer: !!_holdTimer, lastCallout: lastCalloutYear }; };
  window.__flipCount = flip;
    // ★ 注意：物理页号不在这里，而在每张纸的 pageNo 上（左堆 1~110，右堆 111~220，
    //        严格按书脊生长位置从左到右编号；参见 __listPages()）
    //   下面两个是【当前可见】的物理页号，仅供调试
    window.__pageLeftNo  = PAGE0;                                  // 左页恒为 110（左堆最上面那张）
