  // ============ 左侧书页（放文字）与它的金线 ============
  function topLeftPage(){
    var best = null, bl = -1e9;
    allPages.forEach(function(p){
      if (p.sd !== -1) return;
      if (p.level > bl){ bl = p.level; best = p; }
    });
    return best;
  }

  var borderMeshL = null, borderGeoL = null, borderMatL = null;
  var borderTL = 0, borderDirL = 0, borderReadyAtL = 0;
