      if (fadingOverlay.mesh && fadingOverlay.mesh.parent) fadingOverlay.mesh.parent.remove(fadingOverlay.mesh);
      for (var j = fades.length - 1; j >= 0; j--) if (fades[j] === fadingOverlay) fades.splice(j, 1);
