    if (!photoMat3D || !photoMesh3D) return;
    hideBorder(true);                                              // 金线收回
    if (!SHOW_BORDER_R && borderMesh){ bookRoot.remove(borderMesh); borderMesh = null; }
    if (!SHOW_BORDER_L && borderMeshL){ bookRoot.remove(borderMeshL); borderMeshL = null; }
    // ★ 已经在淡出中就不要再触发，否则鼠标扫过一排小点时会不断重置动画 -> 闪烁
    if (fadingOverlay && fadingOverlay.mat === photoMat3D) return;
