  resize(); layoutDots(); buildMarkers(); apply(cur); onScroll(); checkEnter(); loop();

  /* ================= 封面「前言」文字层（方案一：封面状态） ================= */
  //  设计：前言是覆盖在 110/111 上的临时图层
  //        只有 coverMode=true（刚打开、还没碰时间轴）时才可见
