  var OPEN_TITLE  = "前言";
  var OPEN_TEXT_L = "岁月镌刻山河，奋斗铸就华章。一路走来，祖国历经艰辛开拓，冲破重重挑战，书写下震撼世界的发展奇迹。大国工程拔地而起，前沿科技不断突破，民生福祉持续增进，广袤大地焕发蓬勃生机。";
  var OPEN_TEXT_R = "所有辉煌成就，皆源于一代代人接续拼搏。历史的车轮滚滚向前，进步的脚步永不停歇。承过往之荣光，启来日之新章，中华民族始终向着更繁荣、更富强的远方奋勇进发。";
  var coverMode     = true;      // ★ 封面状态
